package com.codepilot1c.core.tools.development;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.development.RunnerProfileStore;
import com.codepilot1c.core.edt.development.DependencyPackages;
import com.codepilot1c.core.edt.development.VanessaPackages;
@ToolMeta(name="edt_runner_profile",category="qa",mutating=true,tags={"workspace","edt"})
public final class EdtRunnerProfileTool extends AbstractTool {
    @Override public String getDescription(){return "Get or save the project's reusable automation paths. package_status/prepare_package need no project and manage pinned Vanessa EPF, VAExtension and client_mcp files only: never install extensions, change trust, create a DB or launch clients. put can omit both vanessa_epf/expected_vanessa_sha256 to obtain verified package defaults; partial overrides are rejected. Default-artifact put returns an observable job_id/next_call for the entire download+profile write; identical active requests reuse it, changed requests are rejected. Poll before checking profile. Explicit artifact pairs retain synchronous put. Package readiness is not live runtime readiness. Start with action=get, profile_id=default: configured=false/state=needs_setup means one-time provisioning is required, not repeated client launches or per-library approvals. put stores verified absolute paths and expected_vanessa_sha256 locally in the EDT workspace. No credentials or arbitrary launch commands are stored. No client is started and no security setting is changed. Use edt_runner_prepare to preview/check trust, edt_runtime_catalog for live Vanessa readiness, then edt_development_run_start with profile_id.";}
    @Override public String getParameterSchema(){return """
        {"type":"object","additionalProperties":false,"properties":{"project":{"type":"string"},"profile_id":{"type":"string","default":"default"},"action":{"type":"string","enum":["get","put","package_status","prepare_package"],"default":"get"},"profile":{"type":"object","description":"For put: platform_bin, target (infobase_path OR server_address+server_infobase), manager_infobase_path, params_template are required; omit both vanessa_epf/expected_vanessa_sha256 to prepare the pinned package automatically, or supply both; user_name, manager_user_name, configuration_name, timeout_s, visual_checkpoint, manager_mcp_port (integer 1..65535, opt-in client_mcp startup) are optional. Paths must be absolute."}}}
        """;}
    @SuppressWarnings("unchecked") @Override protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{var args=p.getRaw();String action=(String)args.getOrDefault("action","get");if(java.util.Set.of("package_status","prepare_package").contains(action)){if(!java.util.Set.of("action").containsAll(args.keySet()))throw new IllegalArgumentException("Only action applies to package preparation");return ToolResult.success(new Gson().toJson(action.equals("package_status")?DependencyPackages.status("vanessa"):DependencyPackages.prepare("vanessa")));}String project=com.codepilot1c.core.edt.development.RuntimeExecutionPlan.required(args,"project");if(args.containsKey("profile_id")&&(!(args.get("profile_id") instanceof String name)||!name.matches("[A-Za-z0-9_-]{1,64}")))throw new IllegalArgumentException("Invalid profile_id");var store=RunnerProfileStore.workspace();Map<String,Object> result;if(action.equals("get")){result=store.get((String)args.get("project"),(String)args.get("profile_id"));if(!Boolean.TRUE.equals(result.get("configured"))){result=new LinkedHashMap<>(result);result.put("automatic_artifact_defaults",true);result.put("required_fields",java.util.List.of("platform_bin","target: infobase_path OR server_address+server_infobase","manager_infobase_path","params_template"));}}else if(action.equals("put")){if(!(args.get("profile") instanceof Map<?,?>)){throw new IllegalArgumentException("profile is required for put");}var profile=(Map<String,Object>)args.get("profile");if(!profile.containsKey("vanessa_epf")&&!profile.containsKey("expected_vanessa_sha256"))result=com.codepilot1c.core.edt.development.RunnerPackageProfilePreparation.shared().prepare(store,project,(String)args.get("profile_id"),profile);else result=com.codepilot1c.core.edt.development.RunnerPackageProfilePreparation.shared().putExplicit(store,project,(String)args.get("profile_id"),VanessaPackages.profileDefaults(profile));}else{throw new IllegalArgumentException("Unknown profile action");}return ToolResult.success(new Gson().toJson(result));}catch(Exception e){return ToolResult.failure("edt_runner_profile: "+e.getMessage());}});}
}
